import datetime
import logging
import re

from jinja2 import Environment, FileSystemLoader, select_autoescape
from pathlib import Path

from taf.nms.netact.command import CommandBuilder

from .mo_class import (
    MoClassFactory,
    MRBTSv1,
    MRBTSv2,
    MRBTSv2CPRIGW
)

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class IntegrationError(Exception):
    pass


class NeIntegrator:
    FRAMEWORK_PATH = '/opt/oss/NSN-AutoIntegrationFramework'
    PERL_PATH = FRAMEWORK_PATH + '/Perl-5.14/bin/perl'
    INITIAL_CONF_GENERATOR_PATH = FRAMEWORK_PATH + '/bin/InitialConfGenerator.pl'
    FINAL_CONF_GENERATOR_PATH = FRAMEWORK_PATH + '/bin/ConfGenerator.pl'
    AUTO_INTEGRATOR_PATH = FRAMEWORK_PATH + '/bin/AutoIntegrator.pl'

    def __init__(self, ssh_was_node):
        self.ssh_was_node = ssh_was_node

        date = datetime.datetime.now().strftime("%Y_%m_%d___%H_%M_%S")
        self.initial_conf_file = f'/tmp/init_conf_file_{date}.xml'
        self.final_conf_file = f'/tmp/final_conf_file_{date}.xml'

    def deintegrate_ne_from_netact(self, dist_name, ignored_errors=None):
        """
        De-integrate Network Element from NetAct using Automatic Integration Framework CLI.

        :param string dist_name: The distinguished name of the network element, e.g.: PLMN-PLMN/MRBTS-1
        :param list(string) ignored_errors: The error is ignored if any list item is a substring of the error line,
            e.g.::

                [
                    'Cnum Fetch Capability failed'
                ]

        :return: de-integration logs
        :rtype: string
        """
        initial_conf_file_content = self._prepare_initial_conf_file(
            "NE-deintegration.jinja2", dist_name=dist_name
        )
        return self._integrate_with_initial_conf(
            initial_conf_file_content, ignored_errors=ignored_errors
        )

    def integrate_ne_with_netact(self, mo_class, mo_release, mr, address, dist_name, **kwargs):
        """
        Integrate NE with NetAct using Automatic Integration Framework CLI.

        :param string mo_class: Supported MO classes: ASI, FHGW, NADCM
        :param string mo_release: SW release, e.g. ASI22R3, FHGW22R3, 24R1 (case-insensitive)
        :param string mr: The maintenance region of network element (created via Monitor Application),
            e.g., ``MRC-COMMON/MR-COMMON``
        :param string address: FQDN of Nokia NE without the trailing dot, or IP address.
        :param string dist_name: The distinguished name for the network element, e.g. PLMN-PLMN/ASI-1

        :return: Integration logs
        :rtype: string
        """
        integrate = kwargs.pop('integrate', True)
        verify = kwargs.pop('verify', True)
        ignored_errors = kwargs.pop('ignored_errors', None)
        mo_class = MoClassFactory.get_mo_class(mo_class)(
            mo_release, mr, address, self.ssh_was_node.username, dist_name, **kwargs
        )
        return self._integrate_with_initial_args(
            mo_class.args, mo_class.kwargs, integrate, verify, ignored_errors
        )

    def integrate_mrbts_with_netact(self, mo_release, mr, mrbts_address, dist_name, presentation_name=None,
                                    http_port='8080', https_port='8443', ip_version='IPV4', security_mode='TLS',
                                    mrbts_em_address=None, certificate_type='Already Installed', cmp=None,
                                    integrate=True, verify=True, ignored_errors=None):
        """
        Integrate MRBTS with NetAct using Automatic Integration Framework CLI.

        :param string mo_release: SW release e.g. SBTS18 or FL19 (case-insensitive).
        :param string mr: The maintenance region of network element (created via Monitor Application),
            e.g., ``MRC-COMMON/MR-COMMON``.
        :param string mrbts_address: Fully qualified domain name of MRBTS (or IP address) or BTS Mediator,
                                     e.g.: 'mrbts-123456' or 'mrbts-123456.btsmed-1'.
        :param string dist_name: The distinguished name of the network element, e.g.: PLMN-PLMN/MRBTS-123456.
        :param string presentation_name: (Optional) The network element name presented on the Monitor.
        :param string http_port: HTTP port where NE3SWS agent is running.
        :param string https_port: HTTPS port where NE3SWS agent is running.
        :param string ip_version: IP protocol version network element uses: 'IPv4' or 'IPv6' (case-insensitive).
        :param string security_mode: TLS (Transport Layer Security) supported: 'TLS' or 'no TLS' (case-insensitive).
        :param string mrbts_em_address: Fully qualified domain name of MRBTS (or IP address), e.g.: 'mrbts-123456'.
            This parameter corresponds to the MRBTS EM address field from WEB UI in case of FL SW releases
            or to SBTS address field in case of SBTS SW releases.
            Please leave default value only if both mentioned fields are not available
            in WEB UI of NE Integration Wizard.
        :param string certificate_type: Allowed values (case-insensitive): ``Already installed`` or ``Install via CMP``.
            If set to ``Install via CMP`` then ``cmp`` parameter must be configured. Parameter supported for
            SBTS releases since 22R3.
        :param dict cmp: If ``certificate_type`` is set to ``Install via CMP`` then ``CMPserverHost``, ``CMPserverPort``,
            ``CMPserverPath``, ``CAName`` attributes are mandatory. Parameter supported for SBTS releases since 22R3.
            Dict must contain the following keys:

                - **CMPserverHost** (string): IP address of the certificate management protocol server,
                - **CMPserverPort** (string): port number to be used for addressing the certificate management \
                    protocol server. Port range: 0-65535,
                - **CMPserverPath** (string): operator-configured CMP directory to be used for addressing the \
                    certificate management protocol server,
                - **CAName** (string): subject name of the certificate,
                - **referenceNo** (string): reference number for accessing the CMP server,
                - **sharedKey** (string): secret shared key for accessing the CMP server,
                - **CAUpdateTime** (string): number of days in advance to when a BTS own trust anchor certificate or \
                    any of the peer trust anchor certificates expires or is due to expire, the \
                    BTS shall raise an alarm. Range: 1-4999,
                - **NEUpdateTime** (string): number of days prior to a BTS certificate expiry, when the BTS \
                    autonomously triggers a CMP update sequence. Range: 1-4999,

            E.g.::

                {
                    'CMPserverHost': '127.0.0.1',
                    'CMPserverPort': '1234',
                    'CMPserverPath': 'serverpath',
                    'CAName': 'name'
                    'referenceNo': '123'
                    'sharedKey': 'key'
                    'CAUpdateTime': '1'
                    'NEUpdateTime': '2'
                }

        :param bool integrate: Specifies if integration phase should be performed
        :param bool verify: Specifies if verification phase should be performed together
            with integration phase - ``integrate`` option is set to ``True``,
            or alone as separate step - ``integrate`` option is set to ``False``
        :param list(string) ignored_errors: The error is ignored if any list item is a substring of the error line,
            e.g.::

                [
                    'Alarm upload for managed object',
                    'Failed to verify NE'
                ]

        :return: integration logs
        :rtype: string
        """
        mo_release = mo_release.upper()

        if mo_release.startswith("SBTS") and mo_release >= "SBTS22R3":
            mrbts_mo = MRBTSv2(
                mo_release, mr, mrbts_address, self.ssh_was_node.username, dist_name,
                presentation_name, http_port, https_port, ip_version, security_mode,
                certificate_type, cmp)
            initial_conf_file_content = self._prepare_initial_conf_file(
                "MRBTS_SBTS.jinja2", **mrbts_mo.kwargs
            )
            return self._integrate_with_initial_conf(
                initial_conf_file_content, integrate, verify, ignored_errors
            )
        elif mo_release.startswith("CPRIGW"):
            mrbts_mo = MRBTSv2CPRIGW(
                mo_release, mr, mrbts_address, self.ssh_was_node.username, dist_name,
                presentation_name, http_port, https_port, ip_version, security_mode)
            initial_conf_file_content = self._prepare_initial_conf_file(
                "MRBTS_CPRIGW.jinja2", **mrbts_mo.kwargs
            )
            return self._integrate_with_initial_conf(
                initial_conf_file_content, integrate, verify, ignored_errors
            )

        mrbts_mo = MRBTSv1(
            mo_release, mr, mrbts_address, self.ssh_was_node.username, dist_name,
            presentation_name, http_port, https_port, ip_version, security_mode,
            mrbts_em_address)
        return self._integrate_mrbts_with_initial_args(
            mrbts_mo, integrate, verify, ignored_errors
        )

    @staticmethod
    def _prepare_initial_conf_file(template_name, **kwargs):
        template_path = Path(__file__).parent / 'templates'
        env = Environment(loader=FileSystemLoader(template_path), autoescape=select_autoescape())
        template = env.get_template(template_name)
        return template.render(**kwargs)

    def _integrate_with_initial_conf(
            self, initial_conf_file_content, integrate=True, verify=True, ignored_errors=None
    ):
        """
        :param string initial_conf_file_content: Content of initial conf file
        :param bool integrate: Specifies if integration phase should be performed
        :param bool verify: Specifies if verification phase should be performed together
            with integration phase - ``integrate`` option is set to ``True``,
            or alone as separate step - ``integrate`` option is set to ``False``
        :param list(string) ignored_errors: The error is ignored if any list item is a substring of the error line,
            e.g.::

                [
                    'Alarm upload for managed object',
                    'Failed to verify NE'
                ]

        """
        with self.ssh_was_node as ssh:
            try:
                ssh.put_file_content(initial_conf_file_content, self.initial_conf_file)
                self._generate_final_conf_file()
                return self._integrate_final_conf_file(integrate, verify, ignored_errors)
            finally:
                command = f"rm -f {self.initial_conf_file.replace('init_', '*')}"
                ssh.execute_command(command)

    def _integrate_mrbts_with_initial_args(
            self, mrbts_mo, integrate=True, verify=True, ignored_errors=None
    ):
        """
        :param MRBTSv1 mrbts_mo: MRBTS Managed Object with attributes required for integration
        :param bool integrate: Specifies if integration phase should be performed
        :param bool verify: Specifies if verification phase should be performed together
            with integration phase - ``integrate`` option is set to ``True``,
            or alone as separate step - ``integrate`` option is set to ``False``
        :param list(string) ignored_errors: The error is ignored if any list item is a substring of the error line,
            e.g.::

                [
                    'Alarm upload for managed object',
                    'Failed to verify NE'
                ]

        """
        na_release = self._get_na_release()

        if na_release in ['Trunk', None] or na_release >= '20':
            return self._integrate_with_initial_args(
                mrbts_mo.args, mrbts_mo.kwargs, integrate, verify, ignored_errors
            )
        else:
            args = mrbts_mo.args + mrbts_mo.additional_args
            return self._integrate_with_initial_args(
                args, {}, integrate, verify, ignored_errors
            )

    def _integrate_with_initial_args(
            self, init_conf_args, init_conf_kwargs, integrate=True, verify=True, ignored_errors=None
    ):
        """
        NOTE: Order of init_conf_args is important for automatic generation of initial conf file.

        :param tuple init_conf_args: Positional arguments for InitialConfGenerator.pl
        :param dict init_conf_kwargs: Keyword arguments for InitialConfGenerator.pl
        :param bool integrate: Specifies if integration phase should be performed
        :param bool verify: Specifies if verification phase should be performed together
            with integration phase - ``integrate`` option is set to ``True``,
            or alone as separate step - ``integrate`` option is set to ``False``
        :param list(string) ignored_errors: The error is ignored if any list item is a substring of the error line,
            e.g.::

                [
                    'Alarm upload for managed object',
                    'Failed to verify NE'
                ]

        """
        with self.ssh_was_node as ssh:
            try:
                self._generate_initial_conf_file(*init_conf_args, **init_conf_kwargs)
                self._generate_final_conf_file()
                return self._integrate_final_conf_file(integrate, verify, ignored_errors)
            finally:
                command = f"rm -f {self.initial_conf_file.replace('init_', '*')}"
                ssh.execute_command(command)

    def _generate_initial_conf_file(self, *args, **kwargs):
        """
        NOTE: Order of args is important for automatic generation of initial conf file.
        """
        arguments = [
            self.INITIAL_CONF_GENERATOR_PATH,
            self.initial_conf_file
        ]
        arguments += [a for a in args if a is not None]
        for k, v in kwargs.items():
            if v is not None:
                arguments.extend([k, v])

        command = CommandBuilder(
            executable=self.PERL_PATH,
            arguments=arguments
        )
        return self._run_command(command.text)

    def _generate_final_conf_file(self):
        command = CommandBuilder(
            executable=self.PERL_PATH,
            arguments=[
                self.FINAL_CONF_GENERATOR_PATH,
                self.initial_conf_file,
                self.final_conf_file
            ]
        )
        return self._run_command(command.text)

    def _integrate_final_conf_file(self, integrate=True, verify=True, ignored_errors=None):
        arguments = [
            self.AUTO_INTEGRATOR_PATH,
            self.final_conf_file,
        ]
        integration_phases = self._set_integration_phases(integrate, verify)
        if integration_phases:
            arguments.append(integration_phases)
        command = CommandBuilder(
            executable=self.PERL_PATH,
            arguments=arguments
        )
        return self._run_command(command.text, ignored_errors=ignored_errors)

    @staticmethod
    def _set_integration_phases(integrate=True, verify=True):
        if integrate and not verify:
            return '-pc'
        elif not integrate and verify:
            return '-v'

    def _run_command(self, command, detailed_logs=True, ignored_errors=None):
        with self.ssh_was_node as ssh:
            output = ssh.execute_command(command, ignore_stderr=detailed_logs, ignore_rc=detailed_logs).stdout
        log_file_content = self._read_logs(output) if detailed_logs else output
        logger.info(log_file_content)
        log_file_content = self._mark_errors_as_ignored(log_file_content, ignored_errors)
        if '| ERROR |' in log_file_content:
            raise IntegrationError(log_file_content)
        return log_file_content

    def _read_logs(self, command_output):
        """
        Exemplary log file paths:
            - /var/opt/oss/log/aif/integration/InitialConfGenerator_init_conf_file_2018_07_11___11_20_31_1531300832_14372.log
            - /var/opt/oss/log/aif/integration/ConfGenerator_init_conf_file_2018_07_11___11_20_31_1531300832_14372.log
            - /var/opt/oss/log/aif/integration/AutoIntegrator_final_conf_file_2018_07_11___11_20_31_1531300835_14420.log
        """
        log_file_path_pattern = re.compile(r'/var/.+\.log')
        log_file_path = re.search(log_file_path_pattern, str(command_output)).group()
        with self.ssh_was_node as ssh:
            try:
                file_content = ssh.get_file_content(log_file_path)
                return file_content.decode(errors='ignore') if isinstance(file_content, bytes) else file_content
            finally:
                command = f"rm -f {log_file_path}"
                ssh.execute_command(command)

    def _get_na_release(self):
        with self.ssh_was_node as ssh:
            output = ssh.execute_command('cat /etc/netact-release').stdout
            matches = re.findall(r'(NetAct(?:\d\d|Trunk)|\d\dR\d-NM)', output)
            if matches:
                return matches[-1].replace('NetAct', '').replace('-NM', '')

    def _mark_errors_as_ignored(self, logs, ignored_errors=None):
        ignored_errors = ignored_errors or []
        if not ignored_errors:
            return logs

        lines = []
        for line in logs.splitlines():
            if '| ERROR |' in line:
                if self._ignore_error(line, ignored_errors):
                    lines.append(line.replace('| ERROR |', '| ERROR - IGNORED |'))
                else:
                    lines.append(line)
            else:
                lines.append(line)
        return '\n'.join(lines)

    @staticmethod
    def _ignore_error(line, ignored_errors):
        return any(e.lower() in line.lower() for e in ignored_errors)
